mapper.sql:
WHERE b.deleted_at IS NULL

    AND b.community_id = #{q.communityId}


    AND h.building_id = #{q.buildingId}


    AND h.unit_id = #{q.unitId}


    AND btrim(b.period) = #{q.period}


    AND b.status = #{q.status}


    AND f.item_code = #{q.itemCode}


    AND b.house_id IS NOT NULL


    AND b.parking_id IS NOT NULL


    AND (b.bill_no ILIKE '%' || #{q.kw} || '%'
         OR h.full_name ILIKE '%' || #{q.kw} || '%'
         OR o.name ILIKE '%' || #{q.kw} || '%')



    AND b.status IN ('待缴', '部分缴')


    AND b.status IN ('待缴', '部分缴')
    AND b.due_date < CURRENT_DATE


    AND b.status = '待缴'


    AND b.status = '部分缴'
